def perform_query(a: List[int], b: List[int], l_a: int, r_a: int, l_b: int, r_b: int) -> int:
    count_a = defaultdict(int)
    count_b = defaultdict(int)
    for i in range(min(l_a, r_a), max(l_a, r_a) + 1):
        count_a[a[i] - 1] += 1
    for i in range(min(l_b, r_b), max(l_b, r_b) + 1):
        count_b[b[i] - 1] += 1
    return sum(min(count_a.get(b_val - 1, 0), count_b.get(a_val - 1, 0)) for a_val, b_val in zip(a, b))

def perform_queries(n: int, m: int, a: List[int], b: List[int]) -> None:
