def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def smallest_n(C, P):
    if is_prime(P):
        if C % P != 0:
            return -1
        else:
            return 0
    else:
        if P - 1 >= C:
            return P - 1
        else:
            return -1

