def merge_sort_permutation(n, k):
    # Quick merge sort to sort array in O(n log n)
    def quick_sort(arr, l, h):
        if l >= h:
            return
        mid = (l + h) // 2
        quick_sort(arr, l, mid)
        quick_sort(arr, mid + 1, h)
        temp = [0] * ((h - l + 1) // 2)
        i, j, k = l, mid + 1, 0
        while i <= mid and j <= h:
            if arr[i] < arr[j]:
                temp[k] = arr[i]
                i += 1
            else:
                temp[k] = arr[j]
                j += 1
            k += 1
        while i <= mid:
            temp[k] = arr[i]
            i += 1
            k += 1
        while j <= h:
            temp[k] = arr[j]
            j += 1
            k += 1
        for i in range(l, h + 1):
            arr[i] = temp[i - l]

    # Dynamic programming calculation of expected number of inversions
    inf = pow(10, 9) // 7
    dp = [[{} for _ in range(n + 1)] for _ in range(k + 1)]

    loop1 = 0
    loop2 = 0
    M = 998244353

    for depth in range(k + 1):
        dp[depth][inf] = [[inf]]
        for i in range(1, n + 1):
            loop1 += 1
            if dp[depth][inf][0] == inf:
                dp[depth][(i - loop1) // 7][inf] = [[inf]]
            else:
                for subproblem in sorted(dp[depth][inf][0], reverse=True):
                    if len(subproblem) < n * depth / (2 * depth + 1):
                        loop2 += 1
                        for s in dp[depth][(n // (2 * depth + 1)) - 1][inf]:
                            if len((subproblem + s).copy()) < n * depth / (2 * depth + 1):
                                dp[depth][n] += [[(s + subproblem).copy()]]
                                break

    return dp[k][(n // (k + 1))][inf][0][-1] // n

