        return first_tree[v][0][1] + first_tree[u-n][0][1]

    elif u > n and u in first_tree and v > n:
        p = find_parv(add_default_parv(int(u/2)), add_default_parv(int(v/2)))
        return first_tree[p][0][1] + first_tree[int(u-p)][0][1]

    elif u > n and u in first_tree and v <= n:
        p = find_parv(add_default_parv(int(u/2)), add_default_parv(int(v/2)))
        return first_tree[p][0][1] + second_tree[int(v-p)][0][1]

    elif u <= n and v > n:
        p = find_parv(add_default_parv(int(u/2)), add_default_parv(int(v/2)))
        return second_tree[p][0][1] + first_tree[int(u-p)][0][1]

    elif u <= n and v > n:
        p = find_parv(add_default_parv(int(u/2)), add_default_parv(int(v/2)))
        return second_tree[p][0][1] + second_tree[int(v-p)][0][1]

def add_default_parv(x):
    res = x
    while res > 0:
        res = res // 2
        yield res

def find_parv(x, parv):
    if parv[x] == x:
        return x
    parv[x] = find_parv(parv[x], parv)
    return parv[x]

