class PowerSystem:
    def __init__(self, num_elements, num_wires, elements):
        self.elements = elements
        self.num_elements = num_elements
        self.num_wires = num_wires

    def solve(self):
        considered = [False] * self.num_elements
        controllers = [0] * self.num_elements

        # Initialize controllers for each element such that power consumption is minimized
        for i in range(self.num_elements):
            if i == 0:
                controllers[i] = 1
            else:
                controllers[i] = 1 - (controllers[i-1] + controllers[(i-1) % self.num_elements])

        # Check if we can produce power greater than or equal to consumed power
        if self._power_consumed() <= self._power_produced():
            return "YES\n" + " ".join(map(str, controllers))

        return "NO"

    def _power_consumed(self):
        return self._wire_heating(0)

    def _power_produced(self):
        return self._wire_sum()

    def _wire_sum(self):
        sum_energy = 0
        for wire in range(self.num_elements):
            for child in range(self.num_elements):
                if self.elements[wire][child][0] != 0 and self.elements[wire][child][1] != 0:
                    sum_energy += self.elements[wire][child][0] * self.elements[wire][child][1]
        return sum_energy

    def _wire_heating(self, x):
        x_squared = x ** 2
        return x_squared * sum(x_squared for wire in range(self.num_elements))
