def get_max_power_consumption(test_case, elements, wires):
    # Sort elements based on the sum of the square of their controllers
    elements.sort(key=lambda x: x[0]**2 + x[1]**2, reverse=True)
    # Connect elements in a circular manner to prevent self-consumption and multiple connections
    connected_elements = [x for x in range(len(elements))]
    for u, v in wires:
        u, v = sorted([u, v])
        # Assign controllers to the wires
        connected_elements[connected_elements.index(u)] = 1
        connected_elements[connected_elements.index(v)] = 1
    # Find the maximum power consumption or production possible with the constraints
    max_production = max(elements[0][0], elements[0][1])
    max_consumption = max(elements[0][0], max_consumption)
    return max_production, max_consumption

