import sys
from collections import defaultdict

def find_smart_bridge(n, m, s, edges):
    # Create a graph from the input edges
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def bfs(s, goal, dist, visited):
        queue = deque([(s, 0)])
        visited[s] = '1'
        while queue:
            u, d = queue.popleft()
            if u == goal:
                return d
            for v, w in graph[u]:
                if visited[v] == '0':
                    visited[v] = '1'
                    queue.append((v, d + w))
        return -1

    bridges = set()
    for u, v in edges:
        if bfs(s, v, 0, {'0', '1'}) > 0 and bfs(s, u, 0, {'0', '1'}) > 0:
            bridges.add((u, v))

    smallest_distance = sys.maxsize
    for u, v in bridges:
        dist = bfs(s, v, 0, {'0', '1'})
        new_distance = max(0, dist - (u == v))
        if new_distance < smallest_distance:
            smallest_distance = new_distance

    return smallest_distance

if __name__ == "__main__":
    n, m, s = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(m)]
    print(find_smart_bridge(n, m, s, edges))
