import sys

def is_permittive(n, m):
    """
    check if it's possible to set the controllers in a way that the consumed power is not greater than power produced
    """
    controller_settings = 0
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) in edges or (j, i) in edges:
                controller_settings += 1
    return controller_settings > 0

def find_solution(n, m, edges):
    """
    find the required integer values
    """
    # For each element, determine the minimum and maximum possible power production
    power_production = [-1] * n
    for i in range(n):
        min_production = i
        max_production = n - i - 1
        for j in range(n):
            for k in range(i, n):
                if (i, j) in edges or (j, k) in edges:
                    if power_production[i] == -1:
                        power_production[i] = min_production
                    else:
                        power_production[i] = min([power_production[i], min_production + k * min_production])
                    if power_production[j] == -1:
                        power_production[j] = max_production
                    else:
                        power_production[j] = max([power_production[j], max_production - j * max_production])
    # Find the element with a power production greater than or equal to its controller power consumption
    for i in range(n):
        if power_production[i] >= i:
            return power_production[i] 
    return -1

def main():
    T = int(input())
    for _ in range(T):
        n, m = map(int, input().split())
        edges = [tuple(map(int, input().split())) for _ in range(m)]
        if is_permittive(n, m):
            print("YES", *find_solution(n, m, edges))
        else:
            print("NO")

if __name__ == "__main__":
    main()
