    for next_row in range(row - 1, row + 2):
        for next_column in range(column - 1, column + 2):
            if next_row >= 0 and next_row < grid_length and next_column >= 0 and next_column < grid_length and tiles[next_row][next_column] == tiles[row][column]:
                dfs(tiles, next_row, next_column, grid_length)
